pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, address recipient, address caller) public {
        vm.assume(caller != recipient);
        vm.assume(recipient != address(0));
        vm.assume(caller != address(this));
        vm.deal(address(c), amount);
        vm.deal(caller, 1 ether);
        bool ok;
        uint256 balanceBefore = recipient.balance;
        vm.prank(caller);
