// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address immutable OWNER = address(this);

    function setUp() public {
        c = new C(OWNER);
    }

    function testFuzz_property(address sender, address recipient) public {
        // Restrict domain to keep it wide but admissible:
        // - sender must not be the owner (otherwise the call is expected to succeed in both versions
        //   and the property holds vacuously for that input)
        // - recipient must not be the same as sender to avoid the trivial succeeding case in the mutant
        //   where the caller IS the recipient (the property is "any non-owner sender reverts", we need
        //   a case where sender is not owner AND sender != recipient to observe the bug)
        vm.assume(sender != OWNER);
        vm.assume(sender != recipient);
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));

        // Fund the contract so there is something to withdraw
        vm.deal(address(c), 1 ether);

        bool ok;
        vm.prank(sender);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract: any call by a non-owner sender always reverts.
        // The buggy contract: fails this when sender == _recipient (the recipient can call successfully).
        assertTrue(!ok);
    }
}

