// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount) public {
        // 1. Keep amount in an admissible domain: non-zero, not exceeding a reasonable bound
        vm.assume(amount > 0 && amount < 1e60);

        // 2. Set up: deal ether to the contract and call withdrawAll with owner as recipient,
        //    which is allowed because msg.sender == owner.
        address ownerAddr = c.owner();
        vm.deal(address(c), amount);
        vm.prank(ownerAddr);

        // 3. Try withdrawing to the owner; the buggy version will revert on the second transfer
        bool ok;
        try c.withdrawAll(ownerAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference must never revert for any admissible input (owner withdrawing to self)
        assertTrue(ok);
    }
}
